!function(){const t=window.location.search;if(!t)return;const e=t.startsWith("?")?t.substring(1):t,d=t=>{if("true"===t.dataset.paramsAdded)return;let d=t.getAttribute("href");if(d){const r=d.includes("?")?"&":"?";t.setAttribute("href",d+r+e),t.dataset.paramsAdded="true"}},r=()=>{document.querySelectorAll("#add-prd, .add-prd").forEach(d)};new MutationObserver(t=>{r()}).observe(document.body,{childList:!0,subtree:!0}),"loading"===document.readyState?document.addEventListener("DOMContentLoaded",r):r()}();